import * as T from 'three';
import {person,box} from './models.js';
export function supplyCrew(world,engines){const records=engines.filter(e=>e.capacity).map(e=>({e,crew:[person(world,0,0,'',true),person(world,0,0,'',true)]}));return(time)=>{for(const {e,crew}of records){const progress=e.supplyProgress||0,active=['scene','reconditioning'].includes(e.status)&&progress>0&&progress<1&&e.supplyAnchor;for(const [i,p]of crew.entries()){p.visible=!!active;if(!active)continue;const walk=Math.min(1,progress/.75);p.position.copy(e.model.position).lerp(e.supplyAnchor,walk).add(new T.Vector3(i?1:-1,0,0));p.position.y=0;p.lookAt(e.supplyAnchor);p.children[1].rotation.x=walk<1?Math.sin(time*7+i)*.5:0;p.children[2].rotation.x=walk<1?-Math.sin(time*7+i)*.5:0;p.children[4].rotation.x=walk<1?-.5:-1.4;p.rotation.z=walk>=1?.18:0;}}};}
